//! Build-time generation of the `keyboardLayout` closed enum.
//!
//! The variant list is NOT hand-written: `keyboard-layouts.txt` next to this
//! crate is generated by `tools/gen-keyboard-layouts.py` from the xkeyboard-config
//! rules XML (evdev.xml) shipped in the image's `xkb-data`, and this script turns
//! that data file into a `&'static [&'static str]` constant. Validating the file
//! here (non-empty, sorted, deduplicated, `layout(variant)` grammar, contains the
//! `us` default) makes a corrupt or hand-edited data file a build failure instead
//! of a runtime surprise.

use std::fmt::Write as _;
use std::path::Path;

const DATA_FILE: &str = "keyboard-layouts.txt";

fn main() {
    let manifest_dir = std::env::var("CARGO_MANIFEST_DIR").expect("cargo sets CARGO_MANIFEST_DIR");
    let data_path = Path::new(&manifest_dir).join(DATA_FILE);
    println!("cargo:rerun-if-changed={DATA_FILE}");

    let text = std::fs::read_to_string(&data_path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", data_path.display()));

    let mut provenance = String::new();
    let mut tokens: Vec<&str> = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if let Some(comment) = line.strip_prefix('#') {
            if provenance.is_empty() {
                provenance = comment.trim().to_string();
            }
            continue;
        }
        tokens.push(line);
    }

    if tokens.is_empty() {
        panic!("{DATA_FILE} contains no layout tokens");
    }
    if !tokens.contains(&"us") {
        panic!("{DATA_FILE} must contain the default layout 'us'");
    }
    for (index, token) in tokens.iter().enumerate() {
        if !valid_token(token) {
            panic!(
                "{DATA_FILE}:{token}: not a `layout` or `layout(variant)` xkb token \
                 (lowercase alnum layout, optional parenthesised variant)"
            );
        }
        if index > 0 {
            match tokens[index - 1].cmp(token) {
                std::cmp::Ordering::Greater => {
                    panic!(
                        "{DATA_FILE} must be sorted: {:?} precedes {token:?}",
                        tokens[index - 1]
                    )
                }
                std::cmp::Ordering::Equal => {
                    panic!("{DATA_FILE} must not contain duplicates: {token:?}")
                }
                std::cmp::Ordering::Less => {}
            }
        }
    }

    let out_dir = std::env::var("OUT_DIR").expect("cargo sets OUT_DIR");
    let generated = Path::new(&out_dir).join("keyboard_layouts.rs");
    let mut source = String::new();
    writeln!(
        source,
        "// @generated by crates/pf-prefs/build.rs from {DATA_FILE}. Do not edit."
    )
    .unwrap();
    writeln!(source, "/// Provenance line from the generated data file.").unwrap();
    writeln!(
        source,
        "pub const KEYBOARD_LAYOUTS_PROVENANCE: &str = {provenance:?};"
    )
    .unwrap();
    writeln!(
        source,
        "/// Every xkb `layout(variant)` token the image ships, sorted."
    )
    .unwrap();
    writeln!(source, "pub const KEYBOARD_LAYOUTS: &[&str] = &[").unwrap();
    for token in &tokens {
        writeln!(source, "    {token:?},").unwrap();
    }
    writeln!(source, "];").unwrap();
    std::fs::write(&generated, source)
        .unwrap_or_else(|e| panic!("cannot write {}: {e}", generated.display()));
}

/// `layout` or `layout(variant)`: the exact grammar the session wiring splits
/// into XKB_DEFAULT_LAYOUT / XKB_DEFAULT_VARIANT. Layout names are lowercase
/// alphanumeric; variant names may additionally carry `_`, `.`, `+` and `-`.
fn valid_token(token: &str) -> bool {
    let (layout, rest) = match token.split_once('(') {
        Some((layout, rest)) => (layout, Some(rest)),
        None => (token, None),
    };
    if layout.is_empty()
        || !layout
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit())
    {
        return false;
    }
    match rest {
        None => true,
        Some(rest) => {
            let variant = match rest.strip_suffix(')') {
                Some(variant) => variant,
                None => return false,
            };
            !variant.is_empty()
                && variant
                    .bytes()
                    .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'_' | b'.' | b'+' | b'-'))
        }
    }
}
